def hometask(arr):
	n = '0'
	if arr.count(0) == 0:
		return -1
	arr.remove(0)
	ans = []
	arr = sorted(arr, reverse=True)
	while arr:
		c = sum(arr) % 3
		if c == 0:
			break
		flag = True
		for i in range(len(arr) - 1, -1, -1):
			if arr[i] % 3 == c:
				arr.pop(i)
				flag = False
				break
		if flag == True:
			for i in range(len(arr) - 1, -1, -1):
				if arr[i] % 3 != 0:
					arr.pop(i)
					flag = False
					break
			for i in range(len(arr) - 1, -1, -1):
				if arr[i] % 3 != 0:
					arr.pop(i)
					flag = False
					break
	if arr == [] or arr[0] == 0:
		return '0'
	ans = ''.join(map(str, sorted(arr, reverse=True)))
	return ans + n
